+	: unknown;
+
+export type WindowFrameBoundary =
+	| { readonly kind: 'unbounded preceding' }
+	| { readonly kind: 'current row' }
+	| { readonly kind: 'unbounded following' }
+	| { readonly kind: 'preceding'; readonly offset: number }
+	| { readonly kind: 'following'; readonly offset: number };
+
+export interface WindowFrame {
+	readonly kind: 'rows' | 'range';
+	readonly from: WindowFrameBoundary;
+	readonly to: WindowFrameBoundary;
+}
+
+export interface WindowSpec {
+	partitionBy?: SQLWrapper | SQLWrapper[];
+	orderBy?: SQLWrapper | SQLWrapper[];
+	frame?: WindowFrame;
+}
+
+export const unboundedPreceding: WindowFrameBoundary = { kind: 'unbounded preceding' };
+export const currentRow: WindowFrameBoundary = { kind: 'current row' };
+export const unboundedFollowing: WindowFrameBoundary = { kind: 'unbounded following' };
+
+function validateOffset(name: string, offset: number): void {
+	if (!Number.isInteger(offset) || offset < 0) {
+		throw new Error(`${name}() requires a non-negative integer, received ${offset}`);
+	}
+}
+
+export function preceding(offset: number): WindowFrameBoundary {
+	validateOffset('preceding', offset);
+	return { kind: 'preceding', offset };
+}
+
+export function following(offset: number): WindowFrameBoundary {
+	validateOffset('following', offset);
+	return { kind: 'following', offset };
+}
+
+function boundaryPosition(boundary: WindowFrameBoundary): number {
+	switch (boundary.kind) {
+		case 'unbounded preceding': return -Infinity;
+		case 'preceding': return -boundary.offset;
+		case 'current row': return 0;
+		case 'following': return boundary.offset;
+		case 'unbounded following': return Infinity;
+	}
+}
+
+function frame(kind: WindowFrame['kind'], spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	if (boundaryPosition(spec.from) > boundaryPosition(spec.to)) {
+		throw new Error('Window frame "from" boundary must not be ordered after "to" boundary');
+	}
+	return { kind, ...spec };
+}
+
+export function rows(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('rows', spec);
+}
+
+export function range(spec: { from: WindowFrameBoundary; to: WindowFrameBoundary }): WindowFrame {
+	return frame('range', spec);
+}
+
+function compileBoundary(boundary: WindowFrameBoundary): SQL {
+	switch (boundary.kind) {
+		case 'preceding': return sql`${sql.raw(String(boundary.offset))} preceding`;
+		case 'following': return sql`${sql.raw(String(boundary.offset))} following`;
+		default: return sql.raw(boundary.kind);
+	}
+}
+
+export function buildWindowSpec(spec: WindowSpec): SQL {
+	const parts: SQL[] = [];
+	if (spec.partitionBy) {
+		const partitionBy = Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy];
+		if (partitionBy.length) parts.push(sql`partition by ${sql.join(partitionBy, sql`, `)}`);
+	}
+	if (spec.orderBy) {
+		const orderBy = Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy];
+		if (orderBy.length) parts.push(sql`order by ${sql.join(orderBy, sql`, `)}`);
+	}
+	if (spec.frame) {
+		parts.push(sql`${sql.raw(spec.frame.kind)} between ${compileBoundary(spec.frame.from)} and ${compileBoundary(spec.frame.to)}`);
+	}
+	return sql.join(parts, sql` `);
+}
+
+export class WindowFunction<T> implements SQLWrapper {
+	constructor(private readonly expression: SQL<T>) {}
+
+	over(spec: WindowSpec): SQL<T>;
+	over(name: string): SQL<T>;
+	over(specOrName: WindowSpec | string): SQL<T> {
+		return typeof specOrName === 'string'
+			? sql`${this.expression} over ${sql.identifier(specOrName)}`
+			: sql`${this.expression} over (${buildWindowSpec(specOrName)})`;
+	}
+
+	getSQL(): SQL<T> {
+		return this.expression;
+	}
+}
+
+function windowFunction<T>(name: string, args: SQL[]): WindowFunction<T> {
+	return new WindowFunction(sql`${sql.raw(name)}(${sql.join(args, sql`, `)})`);
+}
+
+function positiveInteger(name: string, value: number): void {
+	if (!Number.isInteger(value) || value <= 0) {
+		throw new Error(`${name}() requires a positive integer, received ${value}`);
+	}
+}
+
+export function rowNumber(): WindowFunction<number> { return windowFunction('row_number', []); }
+export function rank(): WindowFunction<number> { return windowFunction('rank', []); }
+export function denseRank(): WindowFunction<number> { return windowFunction('dense_rank', []); }
+export function ntile(buckets: number): WindowFunction<number> {
+	positiveInteger('ntile', buckets);
+	return windowFunction('ntile', [sql.raw(String(buckets))]);
+}
+export function percentRank(): WindowFunction<number> { return windowFunction('percent_rank', []); }
+export function cumeDist(): WindowFunction<number> { return windowFunction('cume_dist', []); }
+
+export function lag<T extends SQLWrapper>(expression: T): WindowFunction<SQLValue<T> | null>;
+export function lag<T extends SQLWrapper>(expression: T, offset: number): WindowFunction<SQLValue<T> | null>;
+export function lag<T extends SQLWrapper, TDefault>(expression: T, offset: number, defaultValue: TDefault): WindowFunction<SQLValue<T>>;
+export function lag<T extends SQLWrapper>(expression: T, offset?: number, defaultValue?: unknown): WindowFunction<SQLValue<T> | null> {
+	const args = [sql`${expression}`];
+	if (offset !== undefined) args.push(sql.raw(String(offset)));
+	if (defaultValue !== undefined) args.push(sql`${defaultValue}`);
+	return windowFunction('lag', args);
+}
+
+export function lead<T extends SQLWrapper>(expression: T): WindowFunction<SQLValue<T> | null>;
+export function lead<T extends SQLWrapper>(expression: T, offset: number): WindowFunction<SQLValue<T> | null>;
+export function lead<T extends SQLWrapper, TDefault>(expression: T, offset: number, defaultValue: TDefault): WindowFunction<SQLValue<T>>;
+export function lead<T extends SQLWrapper>(expression: T, offset?: number, defaultValue?: unknown): WindowFunction<SQLValue<T> | null> {
+	const args = [sql`${expression}`];
+	if (offset !== undefined) args.push(sql.raw(String(offset)));
+	if (defaultValue !== undefined) args.push(sql`${defaultValue}`);
+	return windowFunction('lead', args);
+}
+
+export function firstValue<T extends SQLWrapper>(expression: T): WindowFunction<SQLValue<T> | null> { return windowFunction('first_value', [sql`${expression}`]); }
