+export function nthValue<T extends SQLWrapper>(expression: T, nth: number): WindowFunction<SQLValue<T> | null> {
+	positiveInteger('nthValue', nth);
+	return windowFunction('nth_value', [sql`${expression}`, sql.raw(String(nth))]);
+}
