+import { expect, test } from 'vitest';
+
+import { PgDialect, PgSelectBuilder, integer, pgTable } from '~/pg-core/index.ts';
+import {
+	cumeDist,
+	currentRow,
+	denseRank,
+	following,
+	firstValue,
+	lag,
+	lead,
+	lastValue,
+	nthValue,
+	ntile,
+	percentRank,
+	range,
+	rank,
+	rowNumber,
+	rows,
+	unboundedPreceding,
+	windowAvg,
+	windowCount,
+	windowMax,
+	windowMin,
+	windowSum,
+} from '~/sql/index.ts';
+
+const employees = pgTable('employees', { id: integer().notNull(), departmentId: integer(), salary: integer() });
+const dialect = new PgDialect();
+
+function query(expression: ReturnType<typeof rowNumber>['over']) {
+	return dialect.sqlToQuery(expression({})).sql;
+}
+
+test('window helpers emit SQL functions and inline window specifications', () => {
+	expect(query(rowNumber().over.bind(rowNumber()))).toBe('row_number() over ()');
+	expect(dialect.sqlToQuery(rank().over({ orderBy: employees.id })).sql).toBe('rank() over (order by "employees"."id")');
+	expect(dialect.sqlToQuery(denseRank().over({})).sql).toBe('dense_rank() over ()');
+	expect(dialect.sqlToQuery(ntile(4).over({})).sql).toBe('ntile(4) over ()');
+	expect(dialect.sqlToQuery(percentRank().over({})).sql).toBe('percent_rank() over ()');
+	expect(dialect.sqlToQuery(cumeDist().over({})).sql).toBe('cume_dist() over ()');
+	expect(dialect.sqlToQuery(lag(employees.salary, 0).over({})).params).toEqual([]);
+	expect(dialect.sqlToQuery(lead(employees.salary, 2, 0).over({}))).toEqual({ sql: 'lead("employees"."salary", 2, $1) over ()', params: [0] });
+	expect(dialect.sqlToQuery(firstValue(employees.salary).over({})).sql).toBe('first_value("employees"."salary") over ()');
+	expect(dialect.sqlToQuery(lastValue(employees.salary).over({})).sql).toBe('last_value("employees"."salary") over ()');
+	expect(dialect.sqlToQuery(nthValue(employees.salary, 3).over({})).sql).toBe('nth_value("employees"."salary", 3) over ()');
+	expect(dialect.sqlToQuery(windowSum(employees.salary).over({})).sql).toBe('sum("employees"."salary") over ()');
+	expect(dialect.sqlToQuery(windowAvg(employees.salary).over({})).sql).toBe('avg("employees"."salary") over ()');
+	expect(dialect.sqlToQuery(windowMin(employees.salary).over({})).sql).toBe('min("employees"."salary") over ()');
+	expect(dialect.sqlToQuery(windowMax(employees.salary).over({})).sql).toBe('max("employees"."salary") over ()');
+	expect(dialect.sqlToQuery(windowCount().over({})).sql).toBe('count(*) over ()');
+});
+
+test('frames validate and compile positional boundaries without parameters', () => {
+	const frame = rows({ from: unboundedPreceding, to: following(0) });
+	expect(dialect.sqlToQuery(rowNumber().over({ frame })).toEqual({
+		sql: 'row_number() over (rows between unbounded preceding and 0 following)',
+		params: [],
+	});
+	expect(() => range({ from: currentRow, to: unboundedPreceding })).toThrow(/from/);
+	expect(() => following(-1)).toThrow(/following/);
+	expect(() => ntile(0)).toThrow(/ntile.*0/);
+	expect(() => nthValue(employees.id, 0)).toThrow(/nthValue.*0/);
+});
+
+test('named windows are quoted and precede order by', () => {
