+		builder.from(employees).window('ranked', { partitionBy: employees.departmentId, orderBy: employees.id }).orderBy(employees.id).getSQL(),
+	);
+	expect(result.sql).toBe('select row_number() over "ranked" from "employees" window "ranked" as (partition by "employees"."department_id" order by "employees"."id") order by "employees"."id"');
+	expect(() => builder.from(employees).window('', {})).toThrow(/non-empty/);
+	expect(() => builder.from(employees).window('  ', {})).toThrow(/whitespace/);
